from itertools import product

def is_magic_sequence(seq):
    n = len(seq)
    for i in range(n):
        if seq[i] != seq.count(i):
            return False
    return True

# Find all magic sequences of length 5 with x[2] = 2
solutions = []
for seq in product(range(6), repeat=5):
    if seq[2] == 2 and is_magic_sequence(seq):
        solutions.append(seq)

print("Solutions found:", solutions)
